export const RELEASES=[{version:'1.7.0',date:'2 Kasım 2026',title:'Mobil sohbet, MMA-1 ve oyun dengesi',items:['Mobil sohbet küçük simgeyle açılır; menü taşmaları ve GM paneli kaydırması düzeltildi.','MMA-1: hesaba özel 80 milyon oda Gold’u, her 5 saatte yeniden dolar ve diğer odalara taşınmaz.','Hücre hareketi yavaşlatıldı; doğal ve atılan yemler 10 skor verir.','Başlangıçta 80 diken vardır. Yedi yemle boş alana yeni diken çıkar; oda sınırı 800’dür.','Fare tekerleğiyle yakınlaştırma Etrafı Göster açıkken de çalışır; masaüstü menü düğmesi gizlendi.']},{version:'1.6.0',date:'2 Kasım 2026',title:'Oda geçişi, tema ve sohbet düzeltmeleri',items:['Oyundayken farklı odayı seçip Oyna veya İzle ile geçebilirsin. Aynı odada mevcut hücren korunur.','Tekrar yalnızca yutulduktan sonra ve düğmeye basıldığında açılır.','Karanlık, Kenar, Klan ve Etrafı Göster ayarları düzeltildi; kesik hücre halkası kaldırıldı.','Sohbet Haykır, Klan, Takım ve Herkes kanallarına ayrıldı.','Skin yükleme sınırı 2 MB oldu. ZirvePass kapalı: Yakında gelecek.']},{version:'1.5.0',date:'1 Kasım 2026',title:'Sayfam, menü ve GM paneli yenilendi',items:['Ana menü üç sütun, neon oyun çerçevesi ve kompakt kontrollerle yeniden düzenlendi.','Sayfam açık mavi zemine, ortalanmış hesap işlemlerine ve skora göre genişleyen galibiyet kutularına geçti.','GM paneli sol menü, genel bakış, canlı oyuncular, kullanıcılar, odalar, Boost ve ekonomi sayfalarına ayrıldı.','Canlı oyuncu satırından skor ekleme, sohbet yasağı ve oyuncu atma yapılabilir.']},{version:'1.4.0',date:'1 Kasım 2026',title:'Daha kompakt menü ve yeni oda sırası',items:['Masaüstü menüsü ekran yüksekliğine uyarlanır; daha küçük kartlar ve kontroller.','Pin Sorgula menüden kaldırıldı. SPVS-1 ilk sıraya alındı, Boss odası kaldırıldı.','FFA-10’dan sonra Etkinlik-1, Alan-1 ve yeni Alan-2 sıralanır.','Oyun ekranında skor, Gold, sonuç duyuruları ve sağ alt bilgiler yeniden yerleştirildi.']},{version:'1.3.0',date:'1 Kasım 2026',title:'Rekorların son 5 dakikasını izle',items:['Tekrarlar ayrı sekmede açılır; duraklatma, sarma ve hız seçimi vardır.','Onur Tablosu rekor sahibinin turda kullandığı skini gösterir.','Sayfam kupa kartı, Gold/Bonus satırları ve renkli galibiyet kutularıyla yenilendi.','ZirvePass fiyatı 5.000.000 Gold oldu.']}];
export function releaseNews({esc}){const r=RELEASES[0];return `<b>${esc(r.title)}</b><p>Sürüm ${esc(r.version)} · ${esc(r.date)}</p><ul>${r.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button data-page="updates">Tüm güncelleme notları →</button>`}
export function releaseHistory({esc}){return `<div class="doc"><h2>Son Güncellemeler</h2>${RELEASES.map(r=>`<section class="sub-card"><small>${esc(r.date)} · ${esc(r.version)}</small><h3>${esc(r.title)}</h3><ul>${r.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`).join('')}</div>`}
